import { photos } from '../../config/photos.generated.js'

/**
 * Responsive WebP image generated by scripts/optimize-images.mjs.
 * `sizes` should describe the rendered width so the browser picks the right file.
 */
export default function Photo({ name, sizes = '100vw', className = '', priority = false, alt }) {
  const p = photos[name]
  if (!p) {
    if (import.meta.env.DEV) console.warn(`Unknown photo: ${name}`)
    return null
  }
  const srcSet = p.widths.map((w) => `/images/${name}-${w}.webp ${w}w`).join(', ')
  const fallback = `/images/${name}-${p.widths[Math.min(1, p.widths.length - 1)]}.webp`

  return (
    <img
      src={fallback}
      srcSet={srcSet}
      sizes={sizes}
      width={p.width}
      height={p.height}
      alt={alt ?? p.alt}
      loading={priority ? 'eager' : 'lazy'}
      fetchPriority={priority ? 'high' : 'auto'}
      decoding="async"
      className={className}
    />
  )
}
